  const endStop = stops.find(stop => stop.type === "END");

  // Apply optional stop-location fields from user inputs (only when provided,
  // so the defaultPayload values are preserved when an input is left empty).
  function applyLocation(stop, prefix) {
    if (!stop || !stop.location) return;
    const loc = stop.location;
    if (ui[prefix + "_gps"] !== undefined) loc.gps = ui[prefix + "_gps"];
    if (ui[prefix + "_address"] !== undefined) loc.address = ui[prefix + "_address"];
    if (ui[prefix + "_city_code"] !== undefined) {
      loc.city = loc.city ?? {};
      loc.city.code = ui[prefix + "_city_code"];
    }
    if (ui[prefix + "_district"] !== undefined) loc.district = ui[prefix + "_district"];
    if (ui[prefix + "_country_code"] !== undefined) {
      loc.country = loc.country ?? {};
      loc.country.code = ui[prefix + "_country_code"];
    }
    if (ui[prefix + "_area_code"] !== undefined) loc.area_code = ui[prefix + "_area_code"];
