    const loc = stop.location;
    if (ui[prefix + "_gps"] !== undefined) loc.gps = ui[prefix + "_gps"];
    if (ui[prefix + "_address"] !== undefined) loc.address = ui[prefix + "_address"];
    if (ui[prefix + "_city_code"] !== undefined) { loc.city = loc.city ?? {}; loc.city.code = ui[prefix + "_city_code"]; }
